// Validate IN upload request
const body = $input.item.json.body;
const headers = $input.item.json.headers;

if (!headers.authorization) {
  throw new Error('Missing Authorization header');
}

if (!body.municipality || !body.state || !body.instruction_number || !body.version) {
  throw new Error('Missing required fields: municipality, state, instruction_number, version');
}

if (!body.valid_from) {
  throw new Error('Missing required field: valid_from');
}

return {
  json: {
    municipality: body.municipality,
    state: body.state,
    instruction_number: body.instruction_number,
    version: body.version,
    valid_from: body.valid_from,
    valid_until: body.valid_until || null,
    content_text: body.content_text || null,
    content_url: body.content_url || null,
    metadata: body.metadata || {}
  }
};

// Compare with existing version
const newData = $('Validate Input').item.json;
const existingData = $input.item.json;

let isNewVersion = true;
let previousVersion = null;
let previousId = null;

if (existingData && existingData.length > 0) {
  const existing = Array.isArray(existingData) ? existingData[0] : existingData;
  previousVersion = existing.version;
  previousId = existing.id;

  // Check if version is truly different
  if (existing.version === newData.version) {
    isNewVersion = false;
  }
}

return {
  json: {
    ...newData,
    is_new_version: isNewVersion,
    previous_version: previousVersion,
    previous_id: previousId,
    should_insert: isNewVersion
  }
};

// Return duplicate message
const data = $input.item.json;

return {
  json: {
    status: 'duplicate',
    message: `IN ${data.instruction_number} versão ${data.version} já existe`,
    municipality: data.municipality,
    state: data.state
  }
};

// Generate diff description (simplified)
const data = $input.item.json;

let diffDescription = '';

if (data.previous_version) {
  diffDescription = `Atualização da versão ${data.previous_version} para ${data.version}`;
} else {
  diffDescription = `Nova IN ${data.instruction_number} versão ${data.version} cadastrada`;
}

return {
  json: {
    ...data,
    diff_description: diffDescription
  }
};

// Prepare notifications for impacted processes
const inData = $('Generate Diff').item.json;
const processes = $input.all().map(item => item.json);

const notifications = [];

for (const process of processes) {
  notifications.push({
    thread_id: process.thread_id,
    org_id: process.organization_id,
    event_type: 'in_updated',
    title: 'Atualização de IN',
    description: inData.diff_description,
    municipality: inData.municipality,
    state: inData.state,
    in_number: inData.instruction_number,
    new_version: inData.version
  });
}

return notifications.map(notif => ({ json: notif }));

// Build success response
const inData = $('Generate Diff').item.json;
const processes = $('Find Impacted Processes').all();

return {
  json: {
    status: 'success',
    message: 'IN cadastrada com sucesso',
    in_number: inData.instruction_number,
    version: inData.version,
    municipality: inData.municipality,
    state: inData.state,
    diff: inData.diff_description,
    impacted_processes: processes.length
  }
};
